package br.com.wagnertomaszewski.painelmandato;
import org.junit.Test;import static org.junit.Assert.*;
public class BiometriaPlayTest {
 @Test public void origemOficialExataSemHomologacaoOuCredenciaisNaUrl(){assertTrue(PoliticaBiometria.origemPermitida("https://wagnertomaszewski-boop.github.io/cartao-wagner-/painel/index.html#inicio"));for(String u:new String[]{null,"http://wagnertomaszewski-boop.github.io/cartao-wagner-/painel/index.html","https://wagnertomaszewski-boop.github.io.evil/cartao-wagner-/painel/index.html","https://intruso@wagnertomaszewski-boop.github.io/cartao-wagner-/painel/index.html","https://wagnertomaszewski-boop.github.io/cartao-wagner-/v2/index.html","https://mandato-neon-homologacao.onrender.com/hml/","https://wagnertomaszewski-boop.github.io/cartao-wagner-/painel/index.html?token=proibido"})assertFalse(PoliticaBiometria.origemPermitida(u));}
 @Test public void desbloqueioNaoSubstituiLoginCompletoEmAlteracoes(){String api="https://pmmsdjozyyxkbuqlkfpb.supabase.co/";for(String metodo:new String[]{"POST","PATCH","PUT","DELETE"})assertTrue(PoliticaBiometria.exigeLoginCompleto(true,metodo,api+"rest/v1/solicitacoes"));assertFalse(PoliticaBiometria.exigeLoginCompleto(false,"POST",api+"rest/v1/solicitacoes"));assertFalse(PoliticaBiometria.exigeLoginCompleto(true,"GET",api+"rest/v1/solicitacoes"));assertFalse(PoliticaBiometria.exigeLoginCompleto(true,"POST",api+"auth/v1/logout?scope=local"));}
 @Test public void falhaCancelamentoERevogacaoNaoAbremSessao(){PoliticaBiometria p=new PoliticaBiometria();assertFalse(p.validarServidor(false,true,true));assertFalse(p.validarServidor(true,true,false));p.canceladaOuFalhou();assertEquals(PoliticaBiometria.Resultado.BLOQUEADA,p.estado());p.chaveInvalidada();assertEquals(PoliticaBiometria.Resultado.LOGIN_COMPLETO,p.estado());}
}
